CustomField.formula:
IF(
    OR(
        ISBLANK(Scheduled_Start_Time__c),
        ISBLANK(Scheduled_End_Time__c)
    ),
    "",
    TEXT(
        FLOOR(Scheduled_End_Time__c - Scheduled_Start_Time__c)
    ) & " Days " &
    TEXT(
        FLOOR(
            MOD(
                (Scheduled_End_Time__c - Scheduled_Start_Time__c) * 24,
                24
            )
        )
    ) & " Hours " &
    TEXT(
        FLOOR(
            MOD(
                (Scheduled_End_Time__c - Scheduled_Start_Time__c) * 24 * 60,
                60
            )
        )
    ) & " Minutes"
)
